]

_default: Store | None = None


def _store() -> Store:
    global _default
    if _default is None:
        dsn = os.environ.get("FACTSTORE_DSN")
        if not dsn:
            raise FactstoreError("set FACTSTORE_DSN to a factstore credential, or use factstore.connect(dsn)")
        _default = connect(dsn)
    return _default


